package engine_test

import (
	"bytes"
	"log/slog"
	"os"
	"testing"

	"github.com/acityonmars/martian-robots/internal/engine"
)

// commands turns a letter string like "FRL" into commands, failing the test on unknown letters.
func commands(t *testing.T, letters string) []engine.Command {
	t.Helper()
	var cmds []engine.Command
	for _, letter := range letters {
		cmd, ok := engine.CommandFor(letter)
		if !ok {
			t.Fatalf("unknown command letter %q", letter)
		}
		cmds = append(cmds, cmd)
	}
	return cmds
}

func newTestEngine(world *engine.World, plans ...engine.RobotPlan) engine.Engine {
	return engine.NewEngine(world, &engine.Mission{Plans: plans}, slog.New(slog.DiscardHandler))
}

func Test_Run_Prints_One_Line_Per_Robot_And_Scent_Saves_Later_Robot(t *testing.T) {
	world := newTestWorld(engine.Position{X: 5, Y: 3})
	lost := engine.RobotPlan{
		Robot:    &engine.Robot{ID: 0, Pos: engine.Position{X: 3, Y: 2}, Ori: engine.North},
		Commands: commands(t, "FRRFLLFFRRFLL"), // from the spec: falls off the top at 3 3
		World:    world,
	}
	savedByScent := engine.RobotPlan{
		Robot:    &engine.Robot{ID: 1, Pos: engine.Position{X: 3, Y: 3}, Ori: engine.North},
		Commands: commands(t, "F"), // same edge, same cell: the move must be ignored
		World:    world,
	}

	var out bytes.Buffer
	if err := newTestEngine(world, lost, savedByScent).Run(&out); err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	want := "3 3 N LOST\n3 3 N\n"
	if got := out.String(); got != want {
		t.Errorf("output:\n%s\nwant:\n%s", got, want)
	}
}

func Test_Run_Continues_After_Failing_Plan_And_Returns_Error(t *testing.T) {
	world := newTestWorld(engine.Position{X: 5, Y: 3})
	broken := engine.RobotPlan{Robot: nil, World: world} // invalid: no robot
	valid := engine.RobotPlan{
		Robot:    &engine.Robot{ID: 1, Pos: engine.Position{X: 1, Y: 1}, Ori: engine.East},
		Commands: commands(t, "F"),
		World:    world,
	}

	var out bytes.Buffer
	err := newTestEngine(world, broken, valid).Run(&out)

	if err == nil {
		t.Error("Run() error = nil, want error for the broken plan")
	}
	if got, want := out.String(), "2 1 E\n"; got != want {
		t.Errorf("output = %q, want %q (remaining plans still run)", got, want)
	}
}

func Test_Run_Returns_Error_When_Output_Cannot_Be_Written(t *testing.T) {
	world := newTestWorld(engine.Position{X: 5, Y: 3})
	plan := engine.RobotPlan{
		Robot:    &engine.Robot{ID: 0, Pos: engine.Position{X: 1, Y: 1}, Ori: engine.North},
		Commands: commands(t, "F"),
		World:    world,
	}

	// A real file that is already closed: every write fails, like a broken stdout pipe.
	closed, err := os.CreateTemp(t.TempDir(), "out")
	if err != nil {
		t.Fatal(err)
	}
	closed.Close()

	if err := newTestEngine(world, plan).Run(closed); err == nil {
		t.Error("Run() error = nil, want write error")
	}
}
